  "workSurface.widthRules": "Intelligent (par défaut) : un espace de travail selon le contenu, deux remplissent la fenêtre, les conversations se partageant la largeur selon le rapport que vous avez réglé en dernier. Selon le contenu : la colonne de conversation et son {{shelf}} gardent chacun leur largeur, centrés ensemble, avec le bureau des deux côtés. Remplir la fenêtre : les colonnes se partagent toute la largeur de la fenêtre. Ce réglage ne concerne que les largeurs ; les cartes gardent leurs coins, espaces et ombres (le bord à bord est un réglage à part ci-dessous). Faire glisser le bord entre deux panneaux ne modifie que ces deux-là ; double-cliquez pour leurs valeurs par défaut ; déplacer le focus ne change jamais la disposition",
