  "settings.pageHint.nci": "Configurez les mises à jour de l'état des tâches et les notifications d'achèvement à partir de NCI Gadi pour l'hôte sélectionné. Suivez les étapes ci-dessous pour configurer la boîte aux lettres de connexion et de notification.",
  "settings.pageHint.appearance": "Ajustez les couleurs, les polices, la densité de l'interface et l'affichage de l'avatar. Les préférences d'interface sont enregistrées sur cet appareil ; Les modifications de l'avatar {{agent}} sont enregistrées sur leurs hôtes.",
  "settings.pageHint.runtime": "Gérez les runtimes installés et les versions utilisées par {{agents}} sur l'hôte sélectionné. Mettez à jour le programme hôte et le runtime par défaut dans Mises à jour du backend hôte.",
